public static String convertDatesToWeekdays(String date) {
    try {
        String[] parts = date.split(" ");
        if (parts.length != 3) {
            throw new IllegalArgumentException("Date must be in the format 'MM dd yyyy'");
        }

        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        String[] months = {"January", "February", "March", "April", "May", "June",
                           "July", "August", "September", "October", "November", "December"};
        if (month < 1 || month > 12) {
            throw new IllegalArgumentException("Month must be between 01 and 12");
        }

        java.util.Calendar calendar = java.util.Calendar.getInstance();
        calendar.set(year, month - 1, day);

        String[] weekdays = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};
        int dayOfWeek = calendar.get(java.util.Calendar.DAY_OF_WEEK);
        String weekday = weekdays[dayOfWeek - 1];

        return months[month - 1] + " " + day + ", " + year + " is a " + weekday;

    } catch (NumberFormatException e) {
        return "Invalid date format or values. Please use 'MM dd yyyy'.";
    } catch (IllegalArgumentException e) {
        return e.getMessage();
    }
}

