public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }

    StringBuilder result = new StringBuilder();
    boolean forward = true;
    int remaining = s.length();

    while (remaining > 0) {
        if (forward) {
            for (int i = 0; i < 26; i++) {
                if (count[i] > 0) {
                    result.append((char) ('a' + i));
                    count[i]--;
                    remaining--;
                }
            }
        } else {
            for (int i = 25; i >= 0; i--) {
                if (count[i] > 0) {
                    result.append((char) ('a' + i));
                    count[i]--;
                    remaining--;
                }
            }
        }
        forward = !forward;
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    int n = nums.length;
    boolean[][][] dp = new boolean[n + 1][n / 2 + 1][sum + 1];
    dp[0][0][0] = true;

    for (int i = 1; i <= n; i++) {
        for (int j = Math.min(i, n / 2); j >= 1; j--) {
            for (int k = 0; k <= sum; k++) {
                dp[i][j][k] = dp[i - 1][j][k];
                if (!dp[i][j][k] && k >= nums[i - 1]) {
                    dp[i][j][k] = dp[i - 1][j - 1][k - nums[i - 1]];
                }
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0 && dp[n][i][sum * i / n]) {
            return true;
        }
    }

    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length < 2) {
        throw new IllegalArgumentException("Cost array must contain at least two elements.");
    }

    int n = cost.length;
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }

    return Math.min(dp[n - 1], dp[n - 2]);
}

