public int minInsertions(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }

    int openNeeded = 0; // Tracks the number of '(' needed to balance ')'
    int closeNeeded = 0; // Tracks the number of ')' needed to balance '('

    for (char c : s.toCharArray()) {
        if (c == '(') {
            openNeeded++; // Increment openNeeded for each '('
        } else if (c == ')') {
            if (openNeeded > 0) {
                openNeeded--; // Use one '(' to balance this ')'
            } else {
                closeNeeded++; // No '(' to balance this ')', need an extra ')'
            }
        }
    }

    // Total insertions needed is the sum of unmatched '(' and ')'
    return openNeeded + closeNeeded;
}

