public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int maxArea = 0;
    int n = heights.length;
    int[] stack = new int[n];
    int top = -1;

    for (int i = 0; i < n; i++) {
        while (top != -1 && heights[stack[top]] >= heights[i]) {
            int height = heights[stack[top]];
            top--;
            int width = (top == -1) ? i : (i - stack[top] - 1);
            maxArea = Math.max(maxArea, height * width);
        }
        stack[++top] = i;
    }

    while (top != -1) {
        int height = heights[stack[top]];
        top--;
        int width = (top == -1) ? n : (n - stack[top] - 1);
        maxArea = Math.max(maxArea, height * width);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int r = 0, c = 0;

    for (int i = 0; i < result.length; i++) {
        result[i] = mat[r][c];
        if ((r + c) % 2 == 0) { // Moving up
            if (c == cols - 1) {
                r++;
            } else if (r == 0) {
                c++;
            } else {
                r--;
                c++;
            }
        } else { // Moving down
            if (r == rows - 1) {
                c++;
            } else if (c == 0) {
                r++;
            } else {
                r++;
                c--;
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int i = digits.length - 2;

    // Find the first digit that can be swapped to make a larger number
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit is found, return -1
    if (i < 0) {
        return -1;
    }

    // Find the smallest digit on the right side of the found digit that is larger than it
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the digits to the right of the original position of the first found digit
    Arrays.sort(digits, i + 1, digits.length);

    // Convert the character array back to an integer
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1; // In case of overflow or invalid number format
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
