    char[][] pairs = {{'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'}};
    if (n == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
        return result;
    }
    helper(result, new char[n], 0, n - 1, pairs);
