public static int calculateUniqueSum(int[] nums) {
    if (nums == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }

    java.util.Map<Integer, Integer> frequencyMap = new java.util.HashMap<>();
    for (int num : nums) {
        frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
    }

    int uniqueSum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
        if (entry.getValue() == 1) {
            uniqueSum += entry.getKey();
        }
    }

    return uniqueSum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    int[] dp = new int[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
    }
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }

    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();

    for (int i = 0; i < words.length; i++) {
        String reversedWord = new StringBuilder(words[i]).reverse().toString();
        result.append(reversedWord);
        if (i < words.length - 1) {
            result.append(" ");
        }
    }

    return result.toString();
}
